  'TEST-001': { criteria: 'اختبارات وحدة تغطي المنطق الحرج ويمر تنفيذها كاملًا', evidence: 'تقرير تنفيذ اختبارات الوحدة مع قائمة المنطق الحرج المغطى' },
  'TEST-002': { criteria: 'اختبار آلي ينشئ بيانات لمستأجرين اثنين ويثبت أن مستخدم مستأجر (أ) لا يقرأ ولا يعدّل ولا يحذف بيانات مستأجر (ب) (لا تسرّب بيانات بين مستأجرين)', evidence: 'نتيجة اختبار العزل (قراءة/تعديل/حذف عبر المستأجرين) تُظهر رفضًا أو نتيجة فارغة في كل حالة' },
  'TEST-003': { criteria: 'اختبار تزامن يرسل طلبي حجز متزامنين لنفس الموعد والمورد فينجح واحد فقط ويُرفض الآخر (منع الحجز المزدوج)', evidence: 'نتيجة اختبار التزامن تثبت حجزًا واحدًا فقط في قاعدة البيانات رغم الطلبين' },
